// Prevents an overlapping run. The lock is TTL-based (not explicitly released) so a
// crashed run can never leave the workflow permanently locked: it just expires.
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
const lockTtlMs = Number(cfg.runLockMinutes) * 60 * 1000;
const now = Date.now();

if (sd.runLockedAt && now - sd.runLockedAt < lockTtlMs) {
  throw new Error(
    `Previous run still within its lock window (locked at ${new Date(sd.runLockedAt).toISOString()}); skipping this cycle to avoid a duplicate claim race.`
  );
}
sd.runLockedAt = now;
return $input.all();

// A key stuck in "pending" past the stale-claim threshold means a previous run
// crashed (or errored) between Claim and Resolve. Reset it to "failed" so Lookup
// treats it as retry-eligible this cycle, instead of leaving it claimed forever.
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
sd.alerts = sd.alerts || {};
const thresholdMs = Number(cfg.staleClaimMinutes) * 60 * 1000;
const now = Date.now();

for (const key of Object.keys(sd.alerts)) {
  const rec = sd.alerts[key];
  if (rec.status === 'pending' && now - new Date(rec.claimed_at).getTime() >= thresholdMs) {
    rec.status = 'failed';
  }
}
return $input.all();

const cfg = $('Config').first().json;
const staleMs = Number(cfg.staleHours) * 3600 * 1000;
const now = Date.now();
const val = (f) => (f && typeof f === 'object' ? f.value : f);
const disp = (f) => (f && typeof f === 'object' ? (f.display_value || f.value) : f);
const CLOSED_STATES = ['6', '7', '8']; // Resolved, Closed, Canceled

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (CLOSED_STATES.includes(String(val(r.state)))) continue;

  const priority = String(val(r.priority));
  const updatedMs = new Date(String(val(r.sys_updated_on)).replace(' ', 'T') + 'Z').getTime();

  const types = [];
  if (priority === '1') types.push('critical');
  if (priority === '2' && cfg.alertHigh) types.push('high');
  if (Number.isFinite(updatedMs) && now - updatedMs >= staleMs) types.push('stale');

  for (const alertType of types) {
    out.push({
      json: {
        number: val(r.number),
        alertType,
        dedupKey: `${val(r.number)}:${alertType}`,
        priority: disp(r.priority),
        state: disp(r.state),
        stateValue: String(val(r.state)),
        assignedTo: disp(r.assigned_to) || 'Unassigned',
        description: disp(r.short_description),
        lastUpdated: val(r.sys_updated_on) + ' UTC',
        link: `${cfg.instanceUrl}/nav_to.do?uri=incident.do?sys_id=${val(r.sys_id)}`,
        recipient: cfg.recipient,
      },
    });
  }
}
return out;

// Decides, per incident+alertType key, whether this cycle should send:
//   no record            -> send (first alert)
//   status pending        -> skip (another claim is in flight; stale ones were
//                            already reset to "failed" by Recover Stale Claims)
//   status failed         -> send (retry)
//   incident_state changed -> send (e.g. reopened after being resolved)
//   status sent, interval elapsed -> send, flagged as a reminder
//   status sent, interval not elapsed -> skip
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
sd.alerts = sd.alerts || {};
const now = Date.now();
const MIN = 60 * 1000;
const urgentMs = Number(cfg.reminderMinutesUrgent) * MIN;
const staleMs = Number(cfg.reminderHours) * 3600 * 1000;

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const rec = sd.alerts[j.dedupKey];
  const intervalMs = j.alertType === 'stale' ? staleMs : urgentMs;

  let eligible = false;
  let isReminder = false;

  if (!rec) {
    eligible = true;
  } else if (rec.status === 'pending') {
    eligible = false;
  } else if (rec.status === 'failed') {
    eligible = true;
  } else if (rec.incident_state !== j.stateValue) {
    eligible = true;
  } else if (rec.status === 'sent' && now - new Date(rec.last_notified_at).getTime() >= intervalMs) {
    eligible = true;
    isReminder = true;
  }

  if (eligible) out.push({ json: { ...j, isReminder } });
}
return out;

// Written BEFORE the email send attempt. If the workflow crashes right after the
// send, this "pending" record is what Recover Stale Claims finds and retries —
// the store never silently forgets that a send was attempted.
const sd = $getWorkflowStaticData('global');
sd.alerts = sd.alerts || {};
const now = new Date().toISOString();

for (const item of $input.all()) {
  const j = item.json;
  sd.alerts[j.dedupKey] = {
    ...(sd.alerts[j.dedupKey] || {}),
    status: 'pending',
    claimed_at: now,
    incident_state: j.stateValue,
  };
}
return $input.all();

