// Turns a "pending" claim into "sent" (success) or "failed" (retry next run).
// A successful send always gets recorded, even if other emails in the same
// batch failed — so one bad address can't cause a flood of duplicate retries
// for incidents that were already notified successfully.
const sd = $getWorkflowStaticData('global');
sd.alerts = sd.alerts || {};
const claimed = $('Claim Pending').all();
const now = new Date().toISOString();

let failures = 0;
$input.all().forEach((item, i) => {
  const idx = item.pairedItem && item.pairedItem.item !== undefined ? item.pairedItem.item : i;
  const alert = claimed[idx].json;
  if (item.json.error) {
    failures += 1;
    sd.alerts[alert.dedupKey] = { ...sd.alerts[alert.dedupKey], status: 'failed' };
    return;
  }
  sd.alerts[alert.dedupKey] = {
    status: 'sent',
    last_notified_at: now,
    incident_state: alert.stateValue,
  };
});

if (failures > 0) {
  throw new Error(`${failures} alert email(s) failed to send; marked failed and will retry next run.`);
}
return [{ json: { resolved: $input.all().length } }];
